contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 seed) public payable {
        require(seed >= 0);
        c.NETM(); if (__ESBMC_reverted()) return;
        assert(c.balanceOf(address(this)) == 250000000e18);
    }
    receive() external payable {}
}

